-- QuillBot (US - ai-humanizers)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'QuillBot', 'quillbot', 'QuillBot Team', 'support@quillbot.com',
  '+1', NULL, 'https://quillbot.com',
  COALESCE((SELECT id FROM categories WHERE slug='ai-humanizers' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Chicago', 'IL', 'Chicago, IL, US',
  'AI writing tools for paraphrasing, grammar checking, humanizing, and summarizing - used by 35 million writers worldwide.', 'QuillBot is an AI-powered writing platform offering paraphrasing, grammar checking, AI humanization, plagiarism detection, summarization, and translation tools. Founded in 2017 at the University of Illinois Urbana-Champaign, it now serves over 35 million users across 180 countries. The platform is owned by Learneo, Inc. and includes integrations with Google Docs, Microsoft Word, and all major browsers.', 'https://www.google.com/s2/favicons?domain=quillbot.com&sz=256',
  2017, '201-500', 'https://www.linkedin.com/company/quillbot', 'https://twitter.com/TheQuillBot',
  'product', 0,
  '["AI Writing","Paraphrasing Tool","Grammar Checker","AI Humanizer","Plagiarism Checker"]', '["Education","Content Marketing","Publishing","Research & Academia","Journalism","Legal","Business Communications"]', '["Paraphrasing and rewriting content","Humanizing AI-generated text","Grammar and spelling correction","Summarizing long documents","Plagiarism checking","Translating text across 45+ languages","Generating citations (APA, MLA, Chicago)","Detecting AI-generated content"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["AI Paraphraser with 9+ rewriting modes (Standard, Fluency, Formal, Creative, etc.)","AI Humanizer to convert AI-generated text to natural-sounding prose","Advanced Grammar Checker with real-time corrections","AI Detector to identify AI-written content","Plagiarism Checker comparing against billions of web sources","Multi-language Translator supporting 45+ languages","Summarizer for condensing long texts","Citation Generator for APA, MLA, Chicago, Harvard, and IEEE formats","Google Docs and Microsoft Word native integration","Browser extensions for Chrome, Firefox, and Edge"]', '["AI Paraphraser with 9+ rewriting modes (Standard, Fluency, Formal, Creative, etc.)","AI Humanizer to convert AI-generated text to natural-sounding prose","Advanced Grammar Checker with real-time corrections","AI Detector to identify AI-written content","Plagiarism Checker comparing against billions of web sources","Multi-language Translator supporting 45+ languages","Summarizer for condensing long texts","Citation Generator for APA, MLA, Chicago, Harvard, and IEEE formats","Google Docs and Microsoft Word native integration","Browser extensions for Chrome, Firefox, and Edge"]', 'freemium', '[{"name":"Free","price":0,"period":"month","features":["Paraphraser (125-word limit, 2 modes)","Grammar Checker (limited)","Summarizer (1,200-word limit)","Translator (5,000 characters)","Citation Generator and AI Detector"]},{"name":"Premium Monthly","price":19.95,"period":"month","features":["Unlimited paraphrasing with 9+ modes","Advanced Grammar Checker and AI Humanizer","Summarizer (6,000-word limit)","Plagiarism Checker (25,000 words/month)","Unlimited translation"]},{"name":"Premium Annual","price":8.33,"period":"month","features":["All Premium Monthly features","Billed $99.95/year (58% savings vs monthly)","Pause subscription anytime","3-day money-back guarantee"]},{"name":"Teams","price":null,"period":"month","features":["All Premium features for each seat","From $2.91/user/month for 51+ seats","Centralized billing and team management","Volume discounts for 2-50+ users"]}]', '[{"name":"Google Docs","website":"https://docs.google.com","description":"Native add-on for paraphrasing and grammar checking within Google Docs"},{"name":"Microsoft Word","website":"https://www.microsoft.com/word","description":"Word add-in for inline writing assistance"},{"name":"Google Chrome","website":"https://www.google.com/chrome","description":"Browser extension for writing assistance across any web page"},{"name":"Mozilla Firefox","website":"https://www.mozilla.org/firefox","description":"Browser extension for writing assistance on Firefox"},{"name":"Microsoft Edge","website":"https://www.microsoft.com/edge","description":"Browser extension for writing assistance on Edge"}]',
  '["Email support","Help center","Community forum"]', '["Documentation","Video tutorials","Blog"]', '["English"]', '[]', '[{"question":"What is QuillBot used for?","answer":"QuillBot is used to paraphrase, rewrite, humanize AI text, check grammar, detect plagiarism, summarize documents, translate content, and generate academic citations."},{"question":"Does QuillBot have a free plan?","answer":"Yes. The free plan includes basic paraphrasing (125-word limit, 2 modes), grammar checking, summarization, translation up to 5,000 characters, and a citation generator."},{"question":"How much does QuillBot Premium cost?","answer":"QuillBot Premium costs $19.95/month on monthly billing, $13.31/month on a semi-annual plan ($39.95 every 3 months), or $8.33/month on an annual plan ($99.95/year)."},{"question":"Can QuillBot humanize AI-generated text?","answer":"Yes. QuillBot''s AI Humanizer tool rewrites AI-generated content to sound more natural, helping it pass AI detection tools."},{"question":"Does QuillBot integrate with Google Docs and Microsoft Word?","answer":"Yes. QuillBot offers a native Google Docs add-on and a Microsoft Word add-in, plus browser extensions for Chrome, Firefox, and Edge."},{"question":"Is QuillBot safe for academic use?","answer":"QuillBot is widely used by students, but users should always follow their institution''s academic integrity policies when using paraphrasing or AI writing tools."}]', '["Generous free plan suitable for occasional use","9+ paraphrasing modes cover diverse writing styles and needs","Native Google Docs and Microsoft Word integrations","AI Humanizer effectively bypasses AI content detectors","Citations, translation, and plagiarism checking bundled in one platform","Affordable annual pricing at $8.33/month"]', '["Free plan limited to 125-word paraphrasing and basic features only","Plagiarism checker limited to 25,000 words/month even on Premium","AI-generated content can sometimes lose original meaning when paraphrased","Some advanced tools (image generator, PDF editor) feel secondary to core writing features","No native mobile app for offline use"]',
  8.33, 'month', 0, 1, 0, 0,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Bardeen (US - ai-browser-automation)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Bardeen', 'bardeen', 'Bardeen Team', 'support@bardeen.ai',
  '+1', NULL, 'https://bardeen.ai',
  COALESCE((SELECT id FROM categories WHERE slug='ai-browser-automation' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'AI browser automation agent that scrapes data, enriches leads, and automates repetitive go-to-market workflows without code.', 'Bardeen is an AI-powered browser automation platform founded in 2020 by Pascal Weinberger and Artem Harutyunyan in San Francisco. It operates as a Chrome extension that automates repetitive tasks - including web scraping, contact enrichment, CRM updates, and multi-step workflows - for sales, recruiting, and revenue operations teams. The platform has raised $25.3 million and is backed by HubSpot Ventures, Dropbox Ventures, and Insight Partners.', 'https://www.google.com/s2/favicons?domain=bardeen.ai&sz=256',
  2020, '11-50', 'https://www.linkedin.com/company/bardeen', 'https://twitter.com/bardeenai',
  'product', 0,
  '["Browser Automation","AI Workflows","Web Scraping","Lead Enrichment","No-Code Automation"]', '["Sales","Recruiting","Revenue Operations","Marketing","Real Estate","Private Equity"]', '["Automated web scraping and data extraction from any site","AI-powered lead discovery and prospect research","Contact enrichment and email validation","CRM record creation and updating","Multi-step sales outreach automation","Competitive analysis report generation","Recruiting workflow automation","Revenue operations data monitoring"]', '["Freelancers","Small businesses","Midsize companies"]',
  '["Chrome extension-based browser automation with no server setup required","AI-powered web scraper for structured data extraction from any website","AI-driven contact enrichment and email validation","Natural language workflow builder (describe automation in plain English)","100+ pre-built playbook templates for sales and recruiting","AI qualification engine to prioritize leads by fit criteria","Cloud and local execution modes for privacy-sensitive workflows","Integration with CRMs, Google Sheets, Airtable, Notion, and Slack","Credit-based usage system with monthly allocations per plan","Team collaboration features for shared playbooks"]', '["Chrome extension-based browser automation with no server setup required","AI-powered web scraper for structured data extraction from any website","AI-driven contact enrichment and email validation","Natural language workflow builder (describe automation in plain English)","100+ pre-built playbook templates for sales and recruiting","AI qualification engine to prioritize leads by fit criteria","Cloud and local execution modes for privacy-sensitive workflows","Integration with CRMs, Google Sheets, Airtable, Notion, and Slack","Credit-based usage system with monthly allocations per plan","Team collaboration features for shared playbooks"]', 'freemium', '[{"name":"Free","price":0,"period":"month","features":["100 credits per month","Basic web scraping and automation","Access to pre-built templates","Chrome extension"]},{"name":"Basic","price":10,"period":"month","features":["200 credits per month","Premium scraper access","Contact enrichment","Team collaboration"]},{"name":"Premium","price":50,"period":"month","features":["1,000 credits per month (or 12,000/year on annual plan)","All Basic features","Annual billing at $480/year (20% savings)","Priority support"]},{"name":"Enterprise","price":null,"period":"custom","features":["Custom bulk credit allocation","Custom scraper building and maintenance","Premium dedicated support","Annual billing"]}]', '[{"name":"Google Sheets","website":"https://sheets.google.com","description":"Export scraped and enriched data directly into Google Sheets"},{"name":"HubSpot","website":"https://www.hubspot.com","description":"Sync leads and enriched contact data to HubSpot CRM"},{"name":"Salesforce","website":"https://www.salesforce.com","description":"Create and update Salesforce CRM records via automated workflows"},{"name":"LinkedIn","website":"https://www.linkedin.com","description":"Automate prospect research and outreach on LinkedIn"},{"name":"Notion","website":"https://www.notion.so","description":"Push scraped data and research notes into Notion databases"},{"name":"Slack","website":"https://slack.com","description":"Send workflow alerts and automation results to Slack channels"}]',
  '["Email support","Help center","Community forum"]', '["Documentation","Video tutorials","Playbook templates"]', '["English"]', '[]', '[{"question":"What is Bardeen used for?","answer":"Bardeen automates repetitive browser-based tasks for go-to-market teams - including web scraping, lead enrichment, CRM data entry, and multi-step sales workflows - without writing code."},{"question":"Does Bardeen require coding skills?","answer":"No. Bardeen lets users describe automations in plain English or choose from 100+ pre-built templates, requiring no coding or server infrastructure."},{"question":"What browsers does Bardeen support?","answer":"Bardeen currently runs exclusively as a Chrome extension. It does not support Firefox, Safari, or other browsers."},{"question":"How does Bardeen pricing work?","answer":"Bardeen uses a credit-based system. The free plan includes 100 credits/month. Paid plans start at $10/month (Basic, 200 credits) and $50/month (Premium, 1,000 credits). Enterprise pricing is custom."},{"question":"Which CRMs does Bardeen integrate with?","answer":"Bardeen natively integrates with HubSpot and Salesforce, and also connects with Google Sheets, Airtable, Notion, Slack, and LinkedIn."},{"question":"Is there a free plan for Bardeen?","answer":"Yes. Bardeen offers a free plan with 100 credits per month that refreshes at each billing period, covering basic scraping and automation tasks."}]', '["No-code browser automation accessible to non-technical users","Powerful web scraper handles sites without native APIs","Free tier with 100 credits/month for light users","100+ pre-built templates for sales and recruiting workflows","Local execution mode keeps sensitive data on-device","Backed by HubSpot and Dropbox Ventures"]', '["Chrome-only - does not work in Firefox, Safari, or Edge","Credit-based pricing can scale poorly for high-volume users","Limited to browser-based tasks; cannot automate desktop applications","No traditional public API or custom webhooks for developers","Small team (under 30 employees) means slower feature development"]',
  10, 'month', 0, 1, 0, 0,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- ThoughtSpot (US - ai-business-intelligence)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'ThoughtSpot', 'thoughtspot', 'ThoughtSpot Team', 'info@thoughtspot.com',
  '+1', NULL, 'https://www.thoughtspot.com',
  COALESCE((SELECT id FROM categories WHERE slug='ai-business-intelligence' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Mountain View', 'CA', 'Mountain View, CA, US',
  'Agentic analytics platform that lets business users query live data in natural language and get AI-driven insights instantly.', 'ThoughtSpot is an AI-powered business intelligence platform founded in 2012 by Ajeet Singh and Amit Prakash in Mountain View, California. It enables non-technical business users to search live data using natural language and receive AI-generated insights, dashboards, and recommendations through its Spotter AI agent. The platform integrates with Snowflake, Databricks, Google BigQuery, and other cloud data warehouses, and serves financial services, retail, healthcare, and technology sectors.', 'https://www.google.com/s2/favicons?domain=thoughtspot.com&sz=256',
  2012, '500+', 'https://www.linkedin.com/company/thoughtspot', 'https://twitter.com/thoughtspot',
  'product', 0,
  '["Business Intelligence","AI Analytics","Natural Language Queries","Embedded Analytics","Data Visualization"]', '["Financial Services","Retail & CPG","Healthcare & Life Sciences","Technology & Software","Supply Chain & Logistics","Media & Telecom","Procurement"]', '["Natural language querying of live enterprise data","AI-automated dashboard and report generation","Self-service analytics for non-technical business users","Embedded analytics within third-party products","Spotter AI agent for automated data analysis","Semantic layer management for consistent metrics","Real-time decision support for business leaders","Data security and governed access at scale"]', '["Midsize companies","Enterprises"]',
  '["Spotter AI Agent - conversational analyst that answers business questions autonomously","SpotterModel - automated semantic modeling for consistent metric definitions","SpotterViz - instant AI-generated data visualizations and dashboards","SpotterCode - AI-assisted code generation for advanced analytics","Natural language search across live cloud data warehouses","AI-augmented mobile-ready dashboards with automated insights","Low-code embedding SDK and APIs for product teams","Trusted semantic layer with governed metrics and data security","Direct connectivity to Snowflake, Databricks, BigQuery, and Redshift","Integration with Slack, Salesforce, Google Slides, and OpenAI"]', '["Spotter AI Agent - conversational analyst that answers business questions autonomously","SpotterModel - automated semantic modeling for consistent metric definitions","SpotterViz - instant AI-generated data visualizations and dashboards","SpotterCode - AI-assisted code generation for advanced analytics","Natural language search across live cloud data warehouses","AI-augmented mobile-ready dashboards with automated insights","Low-code embedding SDK and APIs for product teams","Trusted semantic layer with governed metrics and data security","Direct connectivity to Snowflake, Databricks, BigQuery, and Redshift","Integration with Slack, Salesforce, Google Slides, and OpenAI"]', 'subscription', '[{"name":"Essentials","price":25,"period":"month","features":["$25/user/month billed annually (5-50 users)","Up to 25M rows of data","Dynamic dashboards and actionable insights","Natural language search"]},{"name":"Pro","price":null,"period":"month","features":["$0.10 per query (usage-based, 25-1,000 users)","Up to 250M rows of data","AI-infused dashboards and Spotter AI Agent","Analyst Studio"]},{"name":"Enterprise","price":null,"period":"custom","features":["Custom pricing for unlimited users and data","Dynamic AI dashboards and Spotter AI Agent","Analyst Studio and full platform access","Dedicated support"]},{"name":"Embedded Developer","price":0,"period":"month","features":["Free for 1 year (up to 10 users, 25M rows)","Embeddable AI dashboards","API and SDK access","For building embedded analytics products"]}]', '[{"name":"Snowflake","website":"https://www.snowflake.com","description":"Direct live query of Snowflake data warehouse without data movement"},{"name":"Databricks","website":"https://www.databricks.com","description":"Native connectivity to Databricks lakehouse for AI-powered analytics"},{"name":"Salesforce","website":"https://www.salesforce.com","description":"Embed ThoughtSpot analytics directly within Salesforce workflows"},{"name":"Slack","website":"https://slack.com","description":"Deliver AI-generated insights and alerts directly into Slack channels"},{"name":"Google BigQuery","website":"https://cloud.google.com/bigquery","description":"Live query against Google BigQuery data warehouse"},{"name":"OpenAI ChatGPT","website":"https://openai.com","description":"ChatGPT integration for conversational analytics experiences"}]',
  '["Email support","Help center","Dedicated account manager","Community forum"]', '["Documentation","Video tutorials","Instructor-led training","Certification programs"]', '["English"]', '["SOC 2","GDPR"]', '[{"question":"What is ThoughtSpot used for?","answer":"ThoughtSpot is used for business intelligence and analytics. It lets non-technical users query live data in natural language and get AI-generated insights, dashboards, and automated recommendations."},{"question":"How does ThoughtSpot Spotter work?","answer":"Spotter is ThoughtSpot''s AI agent that acts as an automated data analyst. Users ask business questions in plain language and Spotter autonomously queries data, generates visualizations, and surfaces relevant insights."},{"question":"What data sources does ThoughtSpot connect to?","answer":"ThoughtSpot connects to major cloud data warehouses including Snowflake, Databricks, Google BigQuery, Amazon Redshift, and Microsoft Azure Synapse."},{"question":"How much does ThoughtSpot cost?","answer":"ThoughtSpot Essentials starts at $25/user/month (billed annually, 5-50 users). The Pro tier is usage-based at $0.10 per query. Enterprise pricing is custom. An Embedded Developer plan is free for the first year."},{"question":"Does ThoughtSpot support embedded analytics?","answer":"Yes. ThoughtSpot offers low-code APIs and SDKs so product teams can embed AI-powered analytics directly within their own applications."},{"question":"Who founded ThoughtSpot and when?","answer":"ThoughtSpot was founded in 2012 by Ajeet Singh and Amit Prakash in Mountain View, California. The company has raised over $600 million in funding and achieved a $4.2 billion valuation."}]', '["Natural language querying enables non-technical users to self-serve analytics","Spotter AI Agent autonomously generates insights and dashboards","Deep integration with leading cloud data platforms (Snowflake, Databricks)","Free 1-year embedded developer tier for product builders","Strong enterprise security with governed semantic layer","$4.2B valuation and 1,700+ employees indicate platform maturity"]', '["Essentials plan limited to 50 users and 25M data rows","Pro plan uses usage-based query pricing which is hard to forecast","Enterprise pricing is custom and opaque - requires sales engagement","Steep learning curve for setting up semantic models correctly","Premium pricing puts it out of reach for smaller businesses"]',
  25, 'month', 1, 0, 1, 1,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

