  COALESCE((SELECT id FROM categories WHERE slug='ai-course-builders' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'New York', 'NY', 'New York, NY, US',
  'Creator-first platform to build, market, and sell online courses, coaching, digital downloads, and memberships.', 'Teachable is a no-code course creation platform founded in 2013 by Ankur Nagpal in New York City. It enables creators, educators, and businesses to build and monetize online courses, coaching programs, digital downloads, and memberships. Acquired by Hotmart Company - the global leader in the creator economy - Teachable has served over 100 million students and enabled creators to earn over $1 billion in revenue. The platform includes AI-powered curriculum generation, quiz creation, subtitle translation, and payment processing.', 'https://www.google.com/s2/favicons?domain=teachable.com&sz=256',
  2013, '201-500', 'https://www.linkedin.com/company/teachable', 'https://twitter.com/teachable',
  'product', 0,
  '["Online Course Platform","Course Builder","AI Curriculum Generator","Creator Economy","E-Learning"]', '["Education & E-Learning","Fitness & Wellness","Business & Entrepreneurship","Creative Arts","Technology & Coding","Finance & Investing","Language Learning"]', '["Creating and selling online video courses","Running one-on-one or group coaching programs","Selling digital downloads (ebooks, templates, guides)","Building recurring revenue membership communities","AI-assisted curriculum and course content generation","Automating student enrollment and drip content delivery","Managing affiliate programs and promotions","Corporate employee training and compliance courses"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["AI Curriculum Generator that builds course outlines from a text description","AI Quiz Generator for interactive student assessments","Automatic video subtitles and translations in 70+ languages","Drag-and-drop course builder with multimedia support","Built-in checkout, payment processing, and subscription billing","Affiliate program management for course promotion","Customizable sales pages and branding (including white-label on Growth+)","Student community and discussion features","Mobile apps for students on iOS and Android","Zapier integration connecting to 150+ external apps"]', '["AI Curriculum Generator that builds course outlines from a text description","AI Quiz Generator for interactive student assessments","Automatic video subtitles and translations in 70+ languages","Drag-and-drop course builder with multimedia support","Built-in checkout, payment processing, and subscription billing","Affiliate program management for course promotion","Customizable sales pages and branding (including white-label on Growth+)","Student community and discussion features","Mobile apps for students on iOS and Android","Zapier integration connecting to 150+ external apps"]', 'subscription', '[{"name":"Starter","price":39,"period":"month","features":["5 products, 100 active students, 1 admin user","7.5% transaction fee on sales","AI creation tools, mobile apps, global payments","Certificates of completion"]},{"name":"Builder","price":89,"period":"month","features":["10 products, 1,000 active students, 1 admin user","0% transaction fee","Affiliate program and real-time support","50 imported students and all Starter features"]},{"name":"Growth","price":189,"period":"month","features":["50 products, 5,000 active students, 5 admin users","0% transaction fee","Branding removal, custom permissions, subtitles/translations","1,000 imported students"]},{"name":"Custom","price":null,"period":"custom","features":["Unlimited products and custom student limits","0% transaction fee","Dedicated success manager and white-glove onboarding","Priority SLA, tax automation, sandbox testing"]}]', '[{"name":"Zapier","website":"https://zapier.com","description":"Connect Teachable with 150+ external apps including Shopify, Discord, and Salesforce"},{"name":"Stripe","website":"https://stripe.com","description":"Native payment processing for course sales, subscriptions, and checkout"},{"name":"Google Analytics","website":"https://analytics.google.com","description":"Track student behavior, funnel performance, and conversion rates"},{"name":"Mailchimp","website":"https://mailchimp.com","description":"Sync student email lists for automated email marketing campaigns"},{"name":"Zoom","website":"https://zoom.us","description":"Run live coaching sessions and virtual classes via Zoom integration"},{"name":"Calendly","website":"https://calendly.com","description":"Schedule coaching appointments and live sessions automatically"}]',
  '["Email support","Help center","Live chat","Community forum"]', '["Documentation","Video tutorials","Webinars","Blog"]', '["English"]', '[]', '[{"question":"What is Teachable used for?","answer":"Teachable is used to create and sell online courses, coaching programs, digital downloads, and membership communities. It is designed for creators, educators, and businesses who want to monetize knowledge and expertise."},{"question":"Does Teachable have a free plan?","answer":"Teachable does not offer a permanent free plan, but it provides a free trial. The entry-level Starter plan begins at $39/month (or $29/month billed annually)."},{"question":"How much does Teachable cost?","answer":"Teachable plans start at $39/month (Starter), $89/month (Builder), and $189/month (Growth). Annual billing reduces prices to $29, $69, and $139/month respectively. A Custom enterprise plan is also available."},{"question":"Does Teachable charge transaction fees?","answer":"Yes, the Starter plan charges a 7.5% transaction fee on sales. The Builder, Growth, and Custom plans have 0% transaction fees."},{"question":"What AI features does Teachable offer?","answer":"Teachable includes an AI Curriculum Generator (creates course outlines from a description), an AI Quiz Generator, and automatic video subtitle and translation in 70+ languages."},{"question":"Does Teachable integrate with Zapier?","answer":"Yes. Teachable''s Growth plan and above include Zapier access, enabling connections to 150+ external tools including Shopify, Discord, Salesforce, Zoom, and Mailchimp."}]', '["AI curriculum and quiz generators accelerate course creation significantly","No-code builder accessible to creators without technical skills","Builder plan and above have 0% transaction fees","100+ million students served demonstrates platform reliability at scale","Video subtitles auto-generated in 70+ languages expand global reach","Hotmart ownership provides global payment infrastructure and creator economy scale"]', '["Starter plan charges 7.5% transaction fee, which cuts into creator revenue","Active student caps on all plans (100/1,000/5,000) can force early upgrades","No built-in community features as robust as dedicated platforms like Circle","Limited product count on Starter (5) and Builder (10) plans","Annual discount requires upfront payment commitment"]',
  29, 'month', 1, 0, 1, 1,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

