  UUID(), 'Be My Eyes', 'be-my-eyes', 'Be My Eyes Team', 'info@bemyeyes.com',
  '+45', NULL, 'https://www.bemyeyes.com',
  COALESCE((SELECT id FROM categories WHERE slug='ai-for-accessibility' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='DK' LIMIT 1), @fallback_country), 'Copenhagen', NULL, 'Copenhagen, Denmark',
  'AI and volunteer-powered app giving blind and low-vision users real-time visual assistance in over 180 languages, 24/7.', 'Be My Eyes is a Danish accessibility company founded in 2015 by Hans Jorgen Wiberg, a craftsman with low vision. Its app connects blind and visually impaired users with sighted volunteers via live video, and with its Be My AI feature (powered by GPT-4 vision), provides instant AI-generated visual descriptions without a human intermediary. The service is free for consumers and available in 150+ countries; business solutions are offered for enterprises seeking to serve visually impaired customers and employees.', 'https://www.google.com/s2/favicons?domain=bemyeyes.com&sz=256',
  2015, '201-500', 'https://www.linkedin.com/company/be-my-eyes', 'https://twitter.com/bemyeyes',
  'product', 0,
  '["Accessibility","AI Visual Assistance","Blind & Low Vision","Volunteer Network","Be My AI"]', '["Accessibility & Assistive Technology","Healthcare","Retail","Hospitality","Telecommunications","Consumer Technology"]', '["Real-time visual assistance for blind and low-vision individuals via live video","AI-powered image and scene description using Be My AI","Workplace accessibility support for blind employees (Be My Eyes Workplace)","Enterprise customer service accessibility via Service Directory","Smart glasses hands-free visual assistance (Meta Ray-Ban, Oakley Meta)","Reading labels, menus, receipts, and product instructions","Navigating new environments and public spaces","Identifying objects, colors, and visual information on demand"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["Live video connection to sighted volunteers for real-time assistance","Be My AI - GPT-4 vision-powered image description without human wait time","Service Directory for connecting with trained enterprise support teams","Smart glasses integration with Meta Ray-Ban and Oakley Meta","Hands-free voice controls for calls and navigation","Be My Eyes Workplace - accessibility solutions for blind employees","Available on iOS, Android, and Windows","24/7 coverage via global volunteer network of 10.5+ million users","180+ language support for global accessibility","Free consumer app with no subscription or paywall for end users"]', '["Live video connection to sighted volunteers for real-time assistance","Be My AI - GPT-4 vision-powered image description without human wait time","Service Directory for connecting with trained enterprise support teams","Smart glasses integration with Meta Ray-Ban and Oakley Meta","Hands-free voice controls for calls and navigation","Be My Eyes Workplace - accessibility solutions for blind employees","Available on iOS, Android, and Windows","24/7 coverage via global volunteer network of 10.5+ million users","180+ language support for global accessibility","Free consumer app with no subscription or paywall for end users"]', 'freemium', '[{"name":"Consumer App","price":0,"period":"month","features":["Full access to volunteer video assistance","Be My AI image description (GPT-4 powered)","Available on iOS, Android, and Windows","180+ language support"]},{"name":"Business / Enterprise","price":null,"period":"custom","features":["Service AI for automated customer service accessibility","Service Connect for trained support agent access","Service Directory listing for brand visibility","Be My Eyes Workplace for employee accessibility programs"]}]', '[{"name":"Meta Ray-Ban Smart Glasses","website":"https://www.meta.com/smart-glasses","description":"Hands-free visual assistance via Ray-Ban Meta and Oakley Meta glasses integration"},{"name":"OpenAI GPT-4 Vision","website":"https://openai.com","description":"Powers Be My AI for instant AI-generated image and scene descriptions"},{"name":"Microsoft Windows","website":"https://www.microsoft.com/windows","description":"Dedicated Windows app for PC-based accessibility assistance"}]',
  '["Email support","Help center","Community forum"]', '["Documentation","Video tutorials","Business onboarding"]', '["English","Danish","Spanish","French","German","Portuguese","Chinese","Arabic"]', '[]', '[{"question":"Is Be My Eyes free to use?","answer":"Yes. The Be My Eyes consumer app is completely free for blind and low-vision users. There is no subscription, trial period, or paywall. Business and enterprise solutions have custom pricing."},{"question":"What is Be My AI?","answer":"Be My AI is an AI-powered feature within the Be My Eyes app, built on OpenAI''s GPT-4 vision model. It provides instant, detailed descriptions of images and scenes without needing a human volunteer."},{"question":"When was Be My Eyes founded?","answer":"Be My Eyes was founded in 2015 by Hans Jorgen Wiberg, a Danish craftsman with low vision. Within 24 hours of launch, 10,000 volunteers had signed up."},{"question":"What platforms does Be My Eyes support?","answer":"Be My Eyes is available on iOS, Android, and Windows. It also integrates with Meta Ray-Ban and Oakley Meta smart glasses for hands-free use."},{"question":"How does Be My Eyes work for businesses?","answer":"Businesses can list in the Be My Eyes Service Directory so visually impaired customers can reach trained support teams directly. Enterprise solutions include Service AI, Service Connect, and Be My Eyes Workplace for employee accessibility."},{"question":"How many people use Be My Eyes?","answer":"As of 2026, Be My Eyes has over 10.5 million sighted volunteers and approximately 1 million blind or low-vision users across 150+ countries and 180+ languages."}]', '["Completely free for blind and low-vision end users - no subscription required","Be My AI delivers instant AI descriptions without waiting for a volunteer","Global volunteer network of 10.5 million ensures 24/7 coverage","Smart glasses integration enables truly hands-free accessibility","Recognized by Time as one of the Best Inventions of 2023","Enterprise solutions extend accessibility to customer service and workplace settings"]', '["Business pricing is fully custom with no publicly listed tiers - requires sales contact","Volunteer response times can vary depending on time zone and language","Be My AI may produce inaccurate descriptions for complex or ambiguous images","Smart glasses integration limited to Meta Ray-Ban and Oakley Meta currently","Core features depend on internet connectivity - no offline mode"]',
  0, 'month', 0, 1, 1, 1,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Tidio (PL - ai-chatbot-builders)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Tidio', 'tidio', 'Tidio Team', 'support@tidio.com',
  NULL, NULL, 'https://www.tidio.com',
  COALESCE((SELECT id FROM categories WHERE slug='ai-chatbot-builders' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='PL' LIMIT 1), @fallback_country), 'Szczecin', NULL, 'Szczecin, Poland',
  'AI-powered customer service software combining live chat, chatbot automation, and the Lyro AI agent for e-commerce and SMBs.', 'Tidio is a customer service platform founded in 2013 that combines live chat, AI chatbots, and the Lyro AI agent to help small and mid-size businesses handle support at scale. The Lyro AI resolves up to 67% of customer queries automatically in under 6 seconds using the company''s own knowledge base. Tidio integrates natively with Shopify, WooCommerce, WordPress, HubSpot, and 30+ other tools, centralising website chat, email, Instagram, and WhatsApp into a single inbox.', 'https://www.google.com/s2/favicons?domain=tidio.com&sz=256',
  2013, '51-200', 'https://www.linkedin.com/company/tidio-ltd/', 'https://x.com/tidiocx',
  'product', 0,
  '["AI Chatbot","Live Chat","Customer Service","E-commerce Support","Lyro AI"]', '["E-commerce","Retail","SaaS","Marketing Agencies","Customer Support","Small Business"]', '["Automated customer support via AI agent","Live chat for e-commerce websites","Order status and product Q&A automation","Lead generation through chat flows","Omnichannel inbox management","Support ticket handling and triage","Proactive chat triggers for visitor engagement"]', '["Freelancers","Small businesses","Midsize companies"]',
  '["Lyro AI agent resolving up to 67% of queries automatically","Live chat widget with real-time typing preview","Multichannel inbox: website, email, Instagram, WhatsApp, Messenger","Visual chatbot flow builder (Flows)","Shopify-native integration with order lookup and product recommendations","Operating hours and auto-assignment rules","Advanced analytics and conversation reporting","Macros and canned responses for agent efficiency","Custom branding and widget customization","OpenAPI access on higher plans"]', '["Lyro AI agent resolving up to 67% of queries automatically","Live chat widget with real-time typing preview","Multichannel inbox: website, email, Instagram, WhatsApp, Messenger","Visual chatbot flow builder (Flows)","Shopify-native integration with order lookup and product recommendations","Operating hours and auto-assignment rules","Advanced analytics and conversation reporting","Macros and canned responses for agent efficiency","Custom branding and widget customization","OpenAPI access on higher plans"]', 'freemium', '[{"name":"Free","price":0,"period":"month","features":["50 billable conversations per month","10 seats","Live chat and ticketing","Basic analytics"]},{"name":"Starter","price":24.17,"period":"month","features":["100 billable conversations per month","50 Lyro AI conversations (one-off)","100 Flows visitors reached","Operating hours"]},{"name":"Growth","price":49.17,"period":"month","features":["Up to 2,000 billable conversations per month","Advanced analytics","Automatic chat assignment","Macros and user permissions"]},{"name":"Plus","price":749,"period":"month","features":["Custom billable conversation volume","Departments and multiproject support","Custom branding","Dedicated success manager and OpenAPI access"]},{"name":"Premium","price":null,"period":"custom","features":["From 3,000 Lyro AI conversations","Guaranteed 50% Lyro AI resolution rate","Pay-per-resolution billing","Mobile SDK and custom analytics"]}]', '[{"name":"Shopify","website":"https://www.shopify.com","description":"Native deep integration enabling AI-powered order lookup, product recommendations, and shipping status within chat."},{"name":"WordPress","website":"https://wordpress.org","description":"One-click no-code plugin install for adding Tidio live chat to any WordPress site."},{"name":"HubSpot","website":"https://www.hubspot.com","description":"Syncs contacts, conversation data, and lead information between Tidio and HubSpot CRM."},{"name":"Zapier","website":"https://zapier.com","description":"Connects Tidio to 8,000+ apps for custom automation workflows beyond native integrations."},{"name":"Zendesk","website":"https://www.zendesk.com","description":"Escalates unresolved Tidio conversations to Zendesk tickets with full chat context."}]',
  '["Email support","Help center","Community forum","Live chat"]', '["Documentation","Video tutorials","Webinars"]', '["English"]', '["GDPR"]', '[{"question":"What is Lyro AI and how does it differ from a regular chatbot?","answer":"Lyro is Tidio''s conversational AI agent powered by Claude. Unlike rule-based chatbots that follow fixed decision trees, Lyro understands natural language and generates contextual answers from your knowledge base, resolving up to 67% of queries automatically without pre-written scripts."},{"question":"Does Tidio have a free plan?","answer":"Yes. Tidio''s free plan includes 50 billable conversations per month, 10 seats, live chat, ticketing, and basic analytics with no time limit."},{"question":"Which e-commerce platforms does Tidio support?","answer":"Tidio has native integrations with Shopify, WooCommerce, BigCommerce, and Adobe Commerce (Magento), with deeper AI features on Shopify including order-status lookups and product recommendations."},{"question":"Can Tidio handle multiple messaging channels in one inbox?","answer":"Yes. Tidio centralises conversations from your website chat, email, Instagram Direct, Facebook Messenger, and WhatsApp into a single shared inbox."},{"question":"Is Tidio GDPR compliant?","answer":"Yes. Tidio is GDPR compliant and provides data processing agreements for EU customers."}]', '["Generous free plan with 50 conversations per month and 10 seats","Lyro AI agent resolves a high percentage of queries without human intervention","Deep Shopify native integration ideal for e-commerce stores","Easy setup with no-code widget for WordPress and most site builders","Unified inbox consolidates chat, email, Instagram, WhatsApp, and Messenger","Transparent per-tier pricing with clear conversation limits"]', '["Conversation-count billing model can lead to unexpected costs during high-traffic periods","Lyro AI requires manual FAQ input with no automatic content synchronization","Limited CRM and advanced marketing tool integration depth compared to dedicated platforms","AI features are primarily template-based, restricting open-ended custom AI workflows","Premium plan pricing is opaque and requires contacting sales"]',
  0, 'month', 0, 1, 1, 1,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Botpress (CA - ai-chatbot-builders)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Botpress', 'botpress', 'Botpress Team', 'info@botpress.com',
  NULL, NULL, 'https://botpress.com',
  COALESCE((SELECT id FROM categories WHERE slug='ai-chatbot-builders' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='CA' LIMIT 1), @fallback_country), 'Montreal', 'QC', 'Montreal, QC, Canada',
  'Enterprise-grade open-source AI agent platform for building, deploying, and managing customer support chatbots across all channels.', 'Botpress is an enterprise AI agent platform founded in 2017 by Sylvain Perron in Quebec, Canada. The platform has deployed over 750,000 AI agents across web, WhatsApp, Slack, Teams, and Messenger, powering customer support for companies of all sizes. Botpress offers a visual drag-and-drop studio, a built-in LLM inference engine, human handoff, and knowledge-base RAG - all without per-seat or per-AI-usage fees on paid plans. It is open-source at its core and supports self-hosted or cloud deployment.', 'https://www.google.com/s2/favicons?domain=botpress.com&sz=256',
  2017, '51-200', 'https://www.linkedin.com/company/botpress/', 'https://x.com/getbotpress',
  'product', 0,
  '["AI Chatbot Builder","Autonomous Agents","Customer Support","Open Source","Enterprise AI"]', '["Customer Support","E-commerce","Financial Services","Healthcare","SaaS","Retail","Technology"]', '["Automated customer support on website and messaging apps","WhatsApp Business chatbot deployment","Internal IT helpdesk automation","Lead qualification and sales chatbot","Knowledge-base FAQ bot with RAG","Human handoff for escalated support tickets","Multi-channel bot from a single configuration"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["Visual drag-and-drop bot studio (Botpress Studio)","LLMz custom inference engine with LLM-agnostic architecture","Knowledge Base with RAG for document and URL ingestion","Multi-channel deployment: web, WhatsApp, Slack, Teams, Messenger, Telegram","Human handoff with full conversation context to live agents","AI Transition intent classification without manual training phrases","Built-in Botpress Desk AI helpdesk module","Role-based access control (RBAC) on Team plan","Self-hosted or managed cloud deployment options","Unlimited bots on all paid plans (as of May 2026)"]', '["Visual drag-and-drop bot studio (Botpress Studio)","LLMz custom inference engine with LLM-agnostic architecture","Knowledge Base with RAG for document and URL ingestion","Multi-channel deployment: web, WhatsApp, Slack, Teams, Messenger, Telegram","Human handoff with full conversation context to live agents","AI Transition intent classification without manual training phrases","Built-in Botpress Desk AI helpdesk module","Role-based access control (RBAC) on Team plan","Self-hosted or managed cloud deployment options","Unlimited bots on all paid plans (as of May 2026)"]', 'freemium', '[{"name":"Free","price":0,"period":"month","features":["100 conversations per month","3 AI agents","1 seat","AI usage included"]},{"name":"Plus","price":150,"period":"month","features":["Unlimited bots","WhatsApp and white-label webchat","Best for solo operators and small teams","No per-seat fees"]},{"name":"Team","price":750,"period":"month","features":["Unlimited bots and unlimited seats","RBAC and team analytics","Conversation routing","Priority support"]},{"name":"Enterprise","price":null,"period":"custom","features":["Voice channel support","Dedicated support and SLAs","Custom data residency","SSO and advanced security"]}]', '[{"name":"Zendesk","website":"https://www.zendesk.com","description":"Manages and escalates support tickets directly from the Botpress agent to Zendesk with full context."},{"name":"Slack","website":"https://slack.com","description":"Enables the AI agent to send and receive messages, handle inquiries, and trigger actions inside Slack channels."},{"name":"WhatsApp Business","website":"https://business.whatsapp.com","description":"Deploy bots on WhatsApp including support for WhatsApp Message Templates for outbound messaging."},{"name":"Microsoft Teams","website":"https://www.microsoft.com/en-us/microsoft-teams/group-chat-software","description":"Runs Botpress AI agents natively inside Microsoft Teams for internal or customer-facing support."}]',
  '["Email support","Help center","Community forum","Documentation"]', '["Documentation","Video tutorials","Community forum"]', '["English"]', '["GDPR","SOC 2"]', '[{"question":"Is Botpress open source?","answer":"Yes. Botpress has an open-source core that you can self-host. The commercial cloud plans (Plus, Team, Enterprise) add managed hosting, priority support, and enterprise features on top of the open-source foundation."},{"question":"How many conversations does the free plan include?","answer":"The free plan includes 100 conversations per month, 3 AI agents, and 1 seat. It is a hard cap with no paid add-ons available on the free tier."},{"question":"Which messaging channels can I deploy Botpress bots on?","answer":"Botpress supports webchat widget, WhatsApp Business, Facebook Messenger, Instagram, Telegram, Slack, Microsoft Teams, and more from a single bot configuration."},{"question":"Does Botpress charge per seat?","answer":"No. As of May 2026, paid plans (Plus and Team) do not charge per seat or per AI usage, making costs more predictable as your team grows."},{"question":"Can Botpress hand off to a human agent?","answer":"Yes. Botpress has a built-in human handoff feature that escalates unresolved conversations to live agents with full conversation context preserved."}]', '["Open-source core with no vendor lock-in and self-hosting option","LLM-agnostic - switch between OpenAI, Anthropic, and other providers easily","No per-seat or per-AI-usage fees on paid plans reduces cost predictability risk","750,000+ deployed agents demonstrates proven scale at enterprise level","Visual studio lowers the barrier for non-developer bot builders","Free plan available with no time limit for prototyping"]', '["Free plan hard-capped at 100 conversations with no add-on option","Jump from Plus ($150/month) to Team ($750/month) is steep for growing teams","Advanced features like voice channel only available on Enterprise custom pricing","May require developer knowledge for complex custom integrations","Pricing changed significantly in May 2026 - older plan comparisons may be inaccurate"]',
  0, 'month', 0, 1, 0, 0,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- FlutterFlow (US - ai-app-builders)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'FlutterFlow', 'flutterflow', 'FlutterFlow Team', 'info@flutterflow.io',
  NULL, NULL, 'https://flutterflow.io',
  COALESCE((SELECT id FROM categories WHERE slug='ai-app-builders' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Mountain View', 'CA', 'Mountain View, CA, US',
  'Visual app development platform for building cross-platform mobile, web, and desktop apps with AI assistance and full Flutter code export.', 'FlutterFlow is a visual no-code and low-code app builder founded in 2020 by former Google engineers Alex Greaves and Abel Mengistu. It enables developers, designers, and non-technical founders to build production-ready Flutter apps for iOS, Android, and web using a drag-and-drop canvas with 200+ pre-built UI components. FlutterFlow natively integrates with Firebase, Supabase, REST APIs, and Stripe, and exports clean, ownable Flutter source code with no vendor lock-in. The platform has over 3.3 million users and is backed by Y Combinator and Google Ventures.', 'https://www.google.com/s2/favicons?domain=flutterflow.io&sz=256',
  2020, '51-200', 'https://www.linkedin.com/company/flutterflow', 'https://x.com/flutterflow',
  'product', 0,
  '["No-Code App Builder","Flutter","Cross-Platform","Visual Development","AI App Builder"]', '["SaaS","E-commerce","Healthcare","Education","Fintech","Startups","Enterprise","Consumer Apps"]', '["Rapid mobile app prototyping and production deployment","Building iOS and Android apps without writing Flutter code","Launching web apps from a single codebase","Team collaboration on app design and logic","Exporting Flutter source code for developer handoff","Integrating Firebase or Supabase backends visually","Creating enterprise internal tools quickly"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["Drag-and-drop WYSIWYG canvas with 200+ pre-built UI components","Action Flow Editor for visual logic and business rules","Native Firebase integration (Auth, Firestore, Storage, Functions, Analytics)","Native Supabase integration with real-time PostgreSQL sync","REST API, GraphQL, and Swagger/OpenAPI import support","GitHub integration and branch-based collaboration on Growth and above","One-click deployment to App Store, Play Store, and web","Full Flutter source code export with no vendor lock-in","Figma frame import for design-to-app workflows","AI-assisted design features for faster layout generation"]', '["Drag-and-drop WYSIWYG canvas with 200+ pre-built UI components","Action Flow Editor for visual logic and business rules","Native Firebase integration (Auth, Firestore, Storage, Functions, Analytics)","Native Supabase integration with real-time PostgreSQL sync","REST API, GraphQL, and Swagger/OpenAPI import support","GitHub integration and branch-based collaboration on Growth and above","One-click deployment to App Store, Play Store, and web","Full Flutter source code export with no vendor lock-in","Figma frame import for design-to-app workflows","AI-assisted design features for faster layout generation"]', 'freemium', '[{"name":"Free","price":0,"period":"month","features":["Up to 2 projects","1,000+ templates","Firebase and Supabase integration","Web publishing"]},{"name":"Basic","price":39,"period":"month","features":["Unlimited projects","Flutter code download","APK download","One-click App Store and Play Store deployment"]},{"name":"Growth","price":80,"period":"month","features":["GitHub integration","Real-time collaboration for 2 users","2 open branches per project","One-click localization and VS Code extension"]},{"name":"Business","price":150,"period":"month","features":["Collaboration up to 5 users","5 open branches per project","Figma frame import and custom typography","CLI access and up to 3 automated tests"]}]', '[{"name":"Firebase","website":"https://firebase.google.com","description":"Native integration covering Authentication, Firestore, Cloud Storage, Cloud Functions, and Analytics for full backend support."},{"name":"Supabase","website":"https://supabase.com","description":"Visual connection to Supabase PostgreSQL with real-time data sync, authentication, and file storage."},{"name":"Stripe","website":"https://stripe.com","description":"Built-in Stripe payment integration for adding in-app purchases and subscription billing without custom code."},{"name":"GitHub","website":"https://github.com","description":"Two-way GitHub sync for version control, CI/CD pipelines, and developer handoff on Growth and above plans."},{"name":"Figma","website":"https://www.figma.com","description":"Import Figma frames directly into FlutterFlow to convert design mockups into functional app screens."}]',
  '["Email support","Help center","Community forum","Video tutorials"]', '["Documentation","Video tutorials","Community forum","Templates library"]', '["English"]', '[]', '[{"question":"Do I need to know how to code to use FlutterFlow?","answer":"No. FlutterFlow is designed for both developers and non-technical users. You can build full apps using the visual drag-and-drop editor without writing code. Developers can also add custom Dart code or custom actions when needed."},{"question":"Can I export the Flutter source code?","answer":"Yes, on the Basic plan ($39/month) and above. You get clean, readable Flutter code that you own completely - there is no lock-in and you can continue building outside FlutterFlow."},{"question":"Which backends does FlutterFlow support natively?","answer":"FlutterFlow natively integrates with Firebase (Auth, Firestore, Storage, Functions) and Supabase (PostgreSQL, Auth, Storage). It also supports REST APIs, GraphQL, and Swagger/OpenAPI imports for any custom backend."},{"question":"Can FlutterFlow apps be published to both iOS App Store and Google Play?","answer":"Yes. FlutterFlow supports one-click deployment to the iOS App Store, Google Play Store, and web from a single codebase on the Basic plan and above."},{"question":"Does FlutterFlow support team collaboration?","answer":"Yes. The Growth plan ($80/month) supports 2 users with GitHub integration and branch-based workflows. The Business plan ($150/month) expands this to 5 users with 5 open branches per project."}]', '["Exports clean, ownable Flutter source code with zero vendor lock-in","Native Firebase and Supabase integration covers 80% of standard app backend needs","3.3M+ users and enterprise adoption at Google, Amazon, and Microsoft validates production readiness","One-click cross-platform deployment to iOS App Store, Google Play, and web","Generous free plan with 2 projects and core integrations included","Active community and extensive template library accelerate development"]', '["Code export and App Store deployment require a paid plan (Basic at $39/month)","Real-time collaboration limited to 2 users on Growth plan and 5 on Business","Saves ~25% with annual billing but monthly rates are the only option shown upfront","Complex custom logic or animations may still require Flutter developer knowledge","Limited built-in automated testing (up to 3 tests on Business plan)"]',
  0, 'month', 0, 1, 0, 0,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Lindy (US - autonomous-agents)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter,
  listing_mode, is_hiring,
  header_tags, industries_served, use_cases, target_company_sizes,
  key_features, features, pricing_model, pricing_tiers, integrations,
  support_channels, training_options, languages, compliance, faqs, pros, cons,
  starting_price, starting_price_period, has_free_trial, has_free_version, has_ios_app, has_android_app,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Lindy', 'lindy', 'Lindy Team', 'info@lindy.ai',
  NULL, NULL, 'https://www.lindy.ai',
  COALESCE((SELECT id FROM categories WHERE slug='autonomous-agents' LIMIT 1), @aiml_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'No-code AI agent builder that creates autonomous AI employees to manage email, meetings, scheduling, CRM updates, and workflows across 4,000+ apps.', 'Lindy is a no-code AI automation platform founded in 2023 by Flo Crivello, a former Uber product manager, and headquartered in San Francisco. The platform lets users build AI agents - called Lindies - by describing tasks in plain English, without writing any code. Each agent handles inbox triage, meeting notes, calendar coordination, CRM updates, and custom workflows by connecting to over 4,000 apps including Gmail, Slack, HubSpot, Salesforce, and Zoom. Trusted by over 400,000 professionals, Lindy has raised $50M in funding from Menlo Ventures, Coatue, and Battery Ventures.', 'https://www.google.com/s2/favicons?domain=lindy.ai&sz=256',
  2023, '11-50', 'https://www.linkedin.com/company/lindyai', 'https://x.com/getlindy',
  'product', 0,
  '["Autonomous AI Agents","No-Code Automation","AI Employee","Workflow Automation","Email AI"]', '["Sales","Customer Success","Recruiting","Marketing","Consulting","SaaS","Real Estate"]', '["Inbox triage and AI email drafting in user''s voice","Automated meeting notes and follow-up generation","Calendar coordination and scheduling management","CRM updates from meeting and call context","Lead research and prospect outreach","Customer support routing and response drafting","Multi-agent chained workflows for complex business processes","iMessage/SMS-based task delegation on mobile"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["Natural language agent creation - describe tasks in plain English","Inbox management with AI triage, prioritization, and reply drafting","Automated meeting lifecycle support - prep, attendance, notes, follow-ups","Calendar coordination with focus-time protection and rescheduling","Multi-agent workflows with handoffs between specialized Lindies","Human approval checkpoints insertable in any workflow","CRM auto-update from conversation and meeting context","iMessage/SMS mobile delegation interface","Training on personal communication style and brand voice","4,000+ app integrations via native connectors"]', '["Natural language agent creation - describe tasks in plain English","Inbox management with AI triage, prioritization, and reply drafting","Automated meeting lifecycle support - prep, attendance, notes, follow-ups","Calendar coordination with focus-time protection and rescheduling","Multi-agent workflows with handoffs between specialized Lindies","Human approval checkpoints insertable in any workflow","CRM auto-update from conversation and meeting context","iMessage/SMS mobile delegation interface","Training on personal communication style and brand voice","4,000+ app integrations via native connectors"]', 'subscription', '[{"name":"Plus","price":49.99,"period":"month","features":["Up to 2 inboxes","Standard usage","Meeting scheduling and email drafting","100+ integrations"]},{"name":"Pro","price":99.99,"period":"month","features":["Everything in Plus","3x usage multiplier","Up to 3 inboxes","Computer use capability"]},{"name":"Max","price":199.99,"period":"month","features":["Everything in Pro","7x usage multiplier","Up to 5 inboxes","Maximum throughput for power users"]},{"name":"Enterprise","price":null,"period":"custom","features":["SSO and SCIM provisioning","HIPAA compliance and BAA","Audit logs and dedicated support","Custom integrations"]}]', '[{"name":"Gmail","website":"https://mail.google.com","description":"Core integration for inbox triage, AI reply drafting, and email-based workflow triggers."},{"name":"HubSpot","website":"https://www.hubspot.com","description":"Automatically updates CRM records, logs meeting notes, and notifies on new company additions."},{"name":"Slack","website":"https://slack.com","description":"Routes Gmail messages to Slack DMs, delivers workflow notifications, and triggers agent actions from Slack."},{"name":"Google Calendar","website":"https://calendar.google.com","description":"Manages scheduling, calendar coordination, and focus-time blocking on behalf of the user."},{"name":"Salesforce","website":"https://www.salesforce.com","description":"Updates Salesforce records with meeting context and automates sales follow-up workflows."}]',
  '["Email support","Help center","Documentation"]', '["Documentation","Video tutorials","Templates"]', '["English"]', '["HIPAA (Enterprise)","SOC 2"]', '[{"question":"What is a ''Lindy'' and how do I create one?","answer":"A Lindy is an AI agent you create by describing what you want it to do in plain English. You specify triggers (e.g., ''when I receive an email from a prospect''), actions (e.g., ''draft a reply in my tone''), and connected apps - no coding required."},{"question":"Does Lindy have a free plan?","answer":"No. Lindy is a paid product starting at $49.99/month. Every plan includes a 7-day free trial with full access to Plus features and no credit card required."},{"question":"Can multiple Lindies work together on a single task?","answer":"Yes. Lindy supports multi-agent workflows where specialized agents hand off tasks to each other. For example, a lead research Lindy can pass enriched data to an outreach Lindy automatically."},{"question":"Is Lindy HIPAA compliant?","answer":"HIPAA compliance with a Business Associate Agreement (BAA) is available on the Enterprise plan. Standard plans (Plus, Pro, Max) are not HIPAA certified."},{"question":"Which AI model does Lindy use?","answer":"Lindy uses multiple underlying LLMs to power its agents. The specific model is not publicly disclosed, as Lindy abstracts model selection to optimize for each task type."},{"question":"Can Lindy manage my calendar and meetings automatically?","answer":"Yes. Lindy can coordinate scheduling, send calendar invites, protect focus time, prepare meeting briefs, take meeting notes, and send follow-ups - all autonomously once configured."}]', '["Plain-English agent setup requires no coding or complex workflow configuration","Multi-agent chaining handles sophisticated multi-step business processes","4,000+ app integrations cover virtually all common business tools","Human approval checkpoints maintain control without blocking automation","HIPAA compliance available on Enterprise for healthcare use cases","7-day free trial on all plans with no credit card required"]', '["No permanent free plan - all usage requires a paid subscription after 7-day trial","Pricing is month-to-month only with no annual billing option to reduce cost","Usage limits (inboxes and throughput) are tied to plan tier, not individual agent count","Relatively young product (founded 2023) with an evolving feature set","Computer use feature limited to Pro plan ($99.99/month) and above"]',
