  'product', 0,
  '["AI for Teachers","K-12 Education","Lesson Planning AI","EdTech","AI Course Builder"]', '["K-12 Education","Higher Education","School Districts","Special Education","EdTech"]', '["AI-generated standards-aligned lesson plans","Rubric and assessment creation in seconds","IEP (Individualized Education Program) drafting for special education","Differentiated instruction materials for diverse learners","Student feedback and class writing feedback generation","Parent and family communication drafts","Professional development content for educators","Student AI interaction rooms with safety moderation"]', '["Freelancers","Small businesses","Midsize companies","Enterprises"]',
  '["80+ AI teacher tools covering planning, assessment, communication, and productivity","50+ AI student tools accessible in moderated Student Rooms","Standards-aligned lesson plan generation in any subject or grade level","Rubric Generator producing rubrics in seconds instead of hours","IEP and differentiated instruction drafting for special education needs","LMS integrations with Google Classroom, Canvas, Schoology, and Clever","One-click export to Google Docs and Microsoft Word","Smart alerts preventing PII leaks, bias, and factual errors","Multilingual content generation for multilingual learner support","SOC 2 Type 2 and FERPA/COPPA/GDPR compliance"]', '["80+ AI teacher tools covering planning, assessment, communication, and productivity","50+ AI student tools accessible in moderated Student Rooms","Standards-aligned lesson plan generation in any subject or grade level","Rubric Generator producing rubrics in seconds instead of hours","IEP and differentiated instruction drafting for special education needs","LMS integrations with Google Classroom, Canvas, Schoology, and Clever","One-click export to Google Docs and Microsoft Word","Smart alerts preventing PII leaks, bias, and factual errors","Multilingual content generation for multilingual learner support","SOC 2 Type 2 and FERPA/COPPA/GDPR compliance"]', 'freemium', '[{"name":"Free","price":0,"period":"month","features":["80+ AI teacher tools","50+ AI student tools","Unlimited student rooms","FERPA, COPPA, SOC 2, GDPR compliant"]},{"name":"Plus","price":12.99,"period":"month","features":["Unlimited AI generations","Unlimited output history and editing (Studio Mode)","MagicSchool Labs early access","Self-paced professional development resources"]},{"name":"Enterprise","price":null,"period":"custom","features":["Institution-wide staff access with SSO and SIS/LMS integration","Custom tool creation and tool management controls","Enhanced student AI moderation and co-branding","White-glove onboarding and dedicated customer success manager"]}]', '[{"name":"Google Classroom","website":"https://classroom.google.com","description":"One-click export of lesson plans, rubrics, and resources directly into Google Classroom assignments."},{"name":"Canvas","website":"https://www.instructure.com/canvas","description":"LMS integration for pushing AI-generated content into Canvas courses and enabling SSO sign-in."},{"name":"Schoology","website":"https://www.instructure.com/schoology","description":"SSO integration and embedded Student Rooms within Schoology course pages for district-wide deployment."},{"name":"Microsoft 365","website":"https://www.microsoft.com/microsoft-365","description":"One-click export of generated content to Microsoft Word, and SSO via Microsoft accounts."},{"name":"Clever","website":"https://clever.com","description":"Roster sync and single sign-on for district-level deployments through Clever identity management."}]',
  '["Email support","Help center","Live chat","Self-serve resources"]', '["Documentation","Video tutorials","Self-paced professional development","Webinars","White-glove onboarding (Enterprise)"]', '["English"]', '["FERPA","COPPA","GDPR","SOC 2 Type 2","Common Sense Privacy Certified"]', '[{"question":"Is MagicSchool free for teachers?","answer":"Yes. The Free plan gives individual teachers unlimited access to all 80+ AI teacher tools and 50+ student tools with no time limit. The Plus plan at $12.99/month (or $99.96/year) adds unlimited generations, Studio Mode editing, and early access to new features."},{"question":"Is MagicSchool safe to use with student data?","answer":"Yes. MagicSchool is FERPA, COPPA, GDPR, and SOC 2 Type 2 certified. Student data is never sold, shared with third parties for advertising, or used to train AI models. The platform holds a 93% privacy rating from Common Sense Education."},{"question":"Which LMS platforms does MagicSchool integrate with?","answer":"MagicSchool integrates with Google Classroom, Canvas, Schoology, and Clever for SSO and roster sync. Teachers can export content directly to Google Docs and Microsoft Word with one click."},{"question":"Can students use MagicSchool directly?","answer":"Yes. Teachers can create moderated Student Rooms where students interact with AI tools in a safe, teacher-controlled environment. The platform includes smart alerts that prevent PII leaks and flag biased or factually incorrect AI outputs."},{"question":"What is the difference between the Free and Plus plans?","answer":"The Free plan has daily generation limits on some tools. The Plus plan ($12.99/month or $99.96/year) removes all generation limits, adds unlimited output history, Studio Mode for editing outputs, early access to MagicSchool Labs, and self-paced professional development content."},{"question":"Does MagicSchool offer district-wide licensing?","answer":"Yes. The Enterprise plan provides institution-wide staff access, full SIS/LMS integration via Clever and ClassLink, custom tool creation, district branding, advanced data dashboards, and white-glove onboarding with a dedicated customer success manager."}]', '["80+ teacher-specific tools address the full range of educator workloads in one platform","Educators report saving 7-10 hours per week on planning and administrative tasks","Strong privacy posture - FERPA, COPPA, SOC 2, GDPR, and Common Sense Privacy Seal (93%)","Student data is never sold or used to train AI models","Generous free plan gives individual teachers access to all core tools at no cost","Deep LMS integrations (Google, Canvas, Schoology) fit existing school workflows"]', '["AI outputs are often text-heavy and static, lacking interactive or multimedia elements for student engagement","Premade AI templates can feel restrictive for teachers wanting open-ended AI exploration","Generation load times can be slow during peak usage","Grade-level calibration of AI-generated content is not always accurate and requires teacher review","Enterprise pricing is opaque and requires a sales conversation for district-level budgeting"]',
  0, 'month', 0, 1, 0, 0,
